"""Journal : correction du texte de C2, décision D13 (plan vectorisation × bruit et grille du Transformer), hypothèses HV1 à HV5 et HT1 à HT4 préinscrites avant tout calcul. Idempotent."""
import sys, pathlib
ROOT = pathlib.Path(__file__).resolve().parents[1]; sys.path.insert(0, str(ROOT / "src"))
import tp2_journal as J, tp2_versions as V
e = [x for x in V.entries() if x["artefact"].startswith("scripts/v3_blockC.py") and x["version"] == "C2"][0]
if "C_diagnostic_openmax_lof.csv" not in (e["pourquoi"] or "") and "diagnostic sur 15 unités" in (e["pourquoi"] or ""):
    V.correct(e["artefact"], "C2", "le shell avait supprimé le nom du fichier de diagnostic dans le texte (accents graves)", pourquoi=e["pourquoi"].replace("(diagnostic sur 15 unités, )", "(diagnostic sur 15 unités, fichier artifacts/results/v3/C_diagnostic_openmax_lof.csv)"))
if not J.exists("D13"):
    J.add("D13", "decision", "Plan de la vectorisation × bruit (bloc V) et de la grille complète du Transformer (bloc T)",
          "**Bloc V (modèles linéaires).** Trois vectorisations (TF-IDF mots, TF-IDF caractères 3 à 5, Skip-gram pondéré IDF) × les six fichiers SIEVE (p = 0 à 0,5, entraînement et test dans le MÊME fichier) × 5 rotations × 2 répétitions (0 et 1) × 5 plis de groupes = 300 unités, développement seul, 400 logs au plus par gabarit et par fichier. Dans chaque unité, MÊMES logs pour deux familles de mesures : macro-F1 des classes connues (palier A) et AUROC de détection d'inconnus (MSP, énergie, MSP de la famille). **Bloc T (Transformer, grille complète).** DistilBERT sans casse (256 jetons, 2 époques, taux 3e-5) × 6 fichiers × 5 rotations × 3 graines (42, 43, 44) = 90 modèles, une seule découpe du développement (répétition 0, pli 0 : mêmes gabarits de test pour tous), 140 logs d'entraînement par classe connue et jusqu'à 133 logs de test par classe, tirage fixe. Chaque unité compare sur LES MÊMES LOGS DE TEST le Transformer et une baseline TF-IDF entraînée sur les mêmes logs d'entraînement. Scores du Transformer : MSP, logit maximal, énergie, MSP de la famille, MSP Monte-Carlo (10 passages), Mahalanobis et kNN sur les vecteurs de 768 valeurs. Les poids ne sont pas conservés (266 Mo par modèle) ; les logits le sont.",
          justification="Demande de l'étudiant (2026-11-07) : comparer les vectorisations selon le bruit et mener en parallèle la grille complète du Transformer. Deux familles de mesures sur les mêmes unités pour que le monde connu et le monde inconnu soient comparables (demande antérieure). La grille complète est réalisable : l'encodeur s'entraîne sur environ 3 400 logs par modèle (environ 3 minutes sur le GPU du Mac).", preuve="scripts/v3_blockV.py ; scripts/v3_transformer_grid.py")
N = "Écrit le 2026-11-07 avant tout calcul des blocs V et T."
H = [
 ("HV1", "Les caractères résistent mieux au bruit que les mots", "La perte de macro-F1 des classes connues entre p = 0 et p = 0,5 est plus petite pour TF-IDF caractères que pour TF-IDF mots (Wilcoxon apparié sur les unités rotation × répétition × pli, Holm p < 0,05).", "Une lettre abîmée ne détruit qu'une partie des n-grammes d'un mot ; un mot déplacé ou collé disparaît entièrement du sac de mots."),
 ("HV2", "Le bruit dégrade chaque vectorisation", "Pour chacune des trois vectorisations, le macro-F1 des classes connues décroît avec p (tendance de Spearman négative, p Holm < 0,05, sur les moyennes par unité).", "Notebook v1 (8.3) : TF-IDF mots 0,49 à p = 0 contre 0,47 à p = 0,5 sur la validation croisée ; la baisse est faible mais attendue."),
 ("HV3", "Skip-gram est moins bon que TF-IDF mots à tous les niveaux de bruit", "À chacun des six niveaux de p, le macro-F1 de Skip-gram pondéré IDF est inférieur à celui de TF-IDF mots (Wilcoxon, Holm p < 0,05 sur les six).", "Notebook v1 : 0,376 contre 0,459 (30 classes, test) ; des vecteurs appris sur peu de contextes distincts."),
 ("HV4", "Le meilleur au propre reste le meilleur au bruit maximal", "La vectorisation au macro-F1 le plus élevé à p = 0 est aussi la meilleure à p = 0,5 (rangs moyens de Friedman).", "Pas de renversement de classement avec le bruit."),
 ("HV5", "Le bruit abaisse la détection d'inconnus", "L'AUROC du MSP décroît avec p pour TF-IDF mots (Spearman négatif, p < 0,05 sur les moyennes par unité).", "Hypothèse exploratoire : un texte plus abîmé rend tous les logs moins typiques de leur classe."),
 ("HT1", "Le Transformer n'améliore pas la classification des classes connues", "Sur les mêmes logs de test, le macro-F1 des classes connues du Transformer dépasse celui de la baseline TF-IDF d'au plus 0,02 (Wilcoxon sur les 30 couples fichier × rotation, moyenne des graines, Holm).", "Notebook v1 : encodeur 0,46 contre TF-IDF 0,49 au test (l'encodeur ne fait pas mieux), hypothèse de décalage de domaine."),
 ("HT2", "Mahalanobis aide sur les vecteurs du Transformer", "L'AUROC de Mahalanobis (vecteurs de 768 valeurs) dépasse celui du MSP du même Transformer d'au moins 0,03 (Wilcoxon sur les 30 couples, Holm p < 0,05).", "Notebook v1 (10.4c) : +0,057 dans les cinq rotations ; Podolskiy et al. et Zhou et al. (sources v1) la donnent efficace sur des Transformers affinés."),
 ("HT3", "La confiance sur la famille aide aussi pour le Transformer", "L'AUROC de la confiance sur la FAMILLE du Transformer dépasse celui de son MSP d'au moins 0,02 (Wilcoxon sur les 30 couples, Holm p < 0,05).", "Extension de la décision D12 (comparaison exploratoire du bloc C, à confirmer sur un autre modèle)."),
 ("HT4", "Le Transformer perd moins avec le bruit que TF-IDF", "La perte de macro-F1 des classes connues entre p = 0 et p = 0,5 est plus petite pour le Transformer que pour la baseline TF-IDF (Wilcoxon sur les 15 couples rotation × graine, p < 0,05).", "Les sous-mots d'un Transformer tolèrent mieux les mots abîmés que le sac de mots."),
]
for i, t, tx, j in H:
    if not J.exists(i): J.add(i, "hypothese", t, tx, justification=j, statut="préinscrite", note=N)
print(J.render()); V.render()
